def is_safe(board, row, col):
    for i in range(row):
        if board[i] == col or abs(board[i] - col) == abs(i - row):
            return False
    return True

def solve_nqueens(n=5, fixed_row=1, fixed_col=2):
    board = [-1] * n
    board[fixed_row] = fixed_col

    def backtrack(row):
        if row == n:
            return True
        if board[row] != -1:  # skip fixed
            return backtrack(row + 1)
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False

    # Check if fixed position is safe with itself (always is)
    if backtrack(0):
        return board
    return None

solution = solve_nqueens()
print(solution)
